// Supabase HTTP yaniti n8n surumune gore ya tek item icinde dizi ya da satir basina bir item olarak gelebilir; ikisini de kaldir.
function normalizeRows(items) {
  if (items.length === 1 && Array.isArray(items[0].json)) return items[0].json;
  if (items.length === 1 && items[0].json && Array.isArray(items[0].json.body)) return items[0].json.body;
  return items.map(i => i.json).filter(j => j && Object.keys(j).length);
}

const profiles = normalizeRows($('Get all profiles').all());
const tasks = normalizeRows($('Get week tasks').all());

const tasksByUser = {};
for (const t of tasks) {
  if (!t || !t.user_id) continue;
  (tasksByUser[t.user_id] = tasksByUser[t.user_id] || []).push(t);
}

const simdiMs = Date.now() + 3 * 3600000;
const simdi_istanbul = new Date(simdiMs).toISOString().replace('Z', '+03:00');

const results = [];
for (const p of profiles) {
  if (!p || !p.id || !p.email) continue;
  const userTasks = tasksByUser[p.id] || [];
  if (userTasks.length === 0) continue; // bos haftada mail gonderilmez (kullanici karari)

  userTasks.sort((a, b) => String(a.start_time || '').localeCompare(String(b.start_time || '')));
  const etkinlik_listesi = userTasks.map(t => `- ${t.name || 'İsimsiz Görev'} | Baslangic: ${t.start_time || t.day}`).join('\n');

  results.push({
    json: {
      email: p.email,
      odul_notu: String(p.motivation_note || '').trim(),
      etkinlik_listesi,
      toplam_is: userTasks.length,
      simdi_istanbul
    }
  });
}

return results;

